# Let me verify by tracing the BFS levels manually
def bfs_trace_levels(graph, start):
    if start not in graph:
        return {}

    levels = {0: {start}}
    visited = {start}
    current_level = 0

    while True:
        next_level_nodes = set()
        for node in levels[current_level]:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_level_nodes.add(neighbor)

        if not next_level_nodes:
            break

        current_level += 1
        levels[current_level] = next_level_nodes

    return levels

levels = bfs_trace_levels(actual_graph, start_node)

for i in range(5):
    print(f"Depth {i}: {sorted(levels.get(i, set()))}")

print(f"\nTotal nodes at depth 4: {len(levels.get(4, set()))}")
